SELECT CASE WHEN ss.units >= 34 THEN 'high' WHEN ss.units >= 18 THEN 'mid' ELSE 'low' END AS units_bucket, MAX(i.quantity) AS max_quantity, MAX(i.last_restock) AS last_last_restock FROM inventory i JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE YEAR(ss.sale_date) = 2024 GROUP BY CASE WHEN ss.units >= 34 THEN 'high' WHEN ss.units >= 18 THEN 'mid' ELSE 'low' END;
